<style>
.school-crud{max-width:1100px;margin:0 auto;padding:20px}.school-crud header{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:12px}.school-btn{display:inline-block;background:#2563eb;color:white;border:0;border-radius:9px;padding:11px 18px;text-decoration:none;cursor:pointer}.school-table-wrap{overflow-x:auto;background:white;border-radius:12px;margin:18px 0}.school-crud table{width:100%;border-collapse:collapse;min-width:680px}.school-crud th,.school-crud td{padding:12px;text-align:left;border-bottom:1px solid #e2e8f0}.school-crud th{background:#f1f5f9}.school-form{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;background:white;padding:24px;border-radius:12px}.school-form label{display:grid;gap:6px;font-weight:600}.school-form input,.school-form select{width:100%;padding:11px;border:1px solid #cbd5e1;border-radius:8px}.school-actions{grid-column:1/-1;display:flex;align-items:center;gap:16px}.school-error{padding:12px;background:#fee2e2;color:#991b1b;border-radius:8px}.school-ok{padding:12px;background:#dcfce7;color:#166534;border-radius:8px}@media(max-width:640px){.school-form{grid-template-columns:1fr;padding:15px}.school-crud{padding:12px}}
</style>
